// The provider lock files of the three roots are committed (owner review M7).
//
// A lock generated by terraform init on one machine carries hashes for that
// platform only and fails on the HCP runners, so the owner generates them for
// every platform once, with network access:
//
//   cd infra/bootstrap  && terraform providers lock -platform=linux_amd64 -platform=windows_amd64 -platform=darwin_arm64
//   cd infra/envs/dev   && terraform providers lock -platform=linux_amd64 -platform=windows_amd64 -platform=darwin_arm64
//   cd infra/envs/prod  && terraform providers lock -platform=linux_amd64 -platform=windows_amd64 -platform=darwin_arm64
//
// and commits the three .terraform.lock.hcl files. Until then this test is skipped
// with that instruction, because the agent that built the stream may not run any
// command that reaches the network registry for other platforms.

import assert from 'node:assert/strict';
import { existsSync, readFileSync } from 'node:fs';
import { resolve } from 'node:path';
import { test } from 'node:test';
import { repoRoot } from './lib.mjs';

const ROOTS = {
  'infra/bootstrap': ['hashicorp/aws', 'hashicorp/tfe'],
  'infra/envs/dev': ['hashicorp/aws'],
  'infra/envs/prod': ['hashicorp/aws'],
};

const INSTRUCTION =
  'lock files are not generated yet: the owner runs terraform providers lock ' +
  '-platform=linux_amd64 -platform=windows_amd64 -platform=darwin_arm64 in infra/bootstrap, ' +
  'infra/envs/dev and infra/envs/prod, then commits the three .terraform.lock.hcl files';

test('every root has a committed provider lock file for every platform', (t) => {
  const missing = Object.keys(ROOTS).filter(
    (dir) => !existsSync(resolve(repoRoot, dir, '.terraform.lock.hcl')),
  );
  if (missing.length > 0) {
    t.skip(`${INSTRUCTION} (missing: ${missing.join(', ')})`);
    return;
  }
  for (const [dir, providers] of Object.entries(ROOTS)) {
    const lock = readFileSync(resolve(repoRoot, dir, '.terraform.lock.hcl'), 'utf8');
    for (const provider of providers) {
      assert.match(lock, new RegExp(`provider "registry\\.terraform\\.io/${provider}"`), dir);
    }
    // A multi-platform lock has more than one h1 hash for each provider.
    const hashes = lock.match(/"h1:[^"]+"/g) ?? [];
    assert.ok(hashes.length >= providers.length * 3, `${dir} must hold hashes for three platforms`);
  }
});
